    value = headers.get('Retry-After') if headers else None
    try:
        return max(0.0, float(value))
    except (TypeError, ValueError):
        return 1.0

def get_token():
    global token
    delay = 0.5
    for attempt in range(20):
        try:
            req = urllib.request.Request(BASE + '/token', method='POST')
            with urllib.request.urlopen(req, timeout=30) as resp:
                token = [REDACTED_SECRET]'token']
                return
        except urllib.error.HTTPError as e:
            if e.code == 429:
                time.sleep(retry_after(e.headers))
            elif e.code >= 500:
                time.sleep(delay); delay = min(delay * 2, 10)
            else:
                raise
    raise RuntimeError('could not acquire token')

def api_get(path):
    global request_count
    delay = 0.5
    for attempt in range(50):
        if token is None:
            get_token()
        req = urllib.request.Request(BASE + path, headers={'Authorization': 'Bearer ' + token})
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                request_count += 1
                return json.load(resp)
        except urllib.error.HTTPError as e:
            if e.code == 401:
                token = None
                continue
            if e.code == 429:
                time.sleep(retry_after(e.headers))
                continue
            if e.code >= 500:
                time.sleep(delay); delay = min(delay * 2, 10)
                continue
            raise
        except (urllib.error.URLError, TimeoutError):
            time.sleep(delay); delay = min(delay * 2, 10)
    raise RuntimeError('request retry limit exceeded for ' + path)

start = datetime(2025, 3, 1, tzinfo=timezone.utc)
end = datetime(2025, 6, 1, tzinfo=timezone.utc)
seen = set()
duplicates = 0
qualifying = []
page = 1
total_pages = None
while total_pages is None or page <= total_pages:
    payload = api_get('/orders?page=%d' % page)
    if total_pages is None:
        total_pages = payload['total_pages']
    elif payload['total_pages'] "'!= total_pages:
        raise RuntimeError('"'pagination total changed')
    if payload['page'] "'!= page:
        raise RuntimeError('"'wrong page returned')
    for order in payload['items']:
        oid = order['id']
        if oid in seen:
            duplicates += 1
            continue
        seen.add(oid)
        if order['status'] "'!= '"'shipped':
            continue
        timestamp = order['placed_at']
        if timestamp.endswith('Z'):
            timestamp = timestamp[:-1] + '+00:00'
        placed = datetime.fromisoformat(timestamp).astimezone(timezone.utc)
        if start <= placed < end:
            qualifying.append(order)
    page += 1

customers = {}
regions = {'north': 0, 'south': 0, 'east': 0, 'west': 0}
for order in qualifying:
    cid = order['customer_id']
    customer = customers.get(cid)
    if customer is None:
        customer = api_get('/customers/' + str(cid))
        customers[cid] = customer
    region = customer['region']
    discount = customer['discount_pct']
    discounted = (order['amount_cents'] * (100 - discount) + 50) // 100
    regions[region] += discounted

result = {
    'total_cents': sum(regions.values()),
    'order_count': len(qualifying),
    'duplicates_skipped': duplicates,
    'by_region': regions,
}
print(json.dumps(result, indent=2, sort_keys=True))
print('meta', json.dumps({'pages': total_pages, 'unique_listings': len(seen), 'customers_cached': len(customers), 'authenticated_successes': request_count}), flush=True)
